<?php
/** Proof — apply (spec "Proof", 3): send=no returns the text and writes no message; send=yes writes one public reply, applies → Pending and +hardware, bumps usage, logs canned.apply and ticket.reply; a status the table forbids is skipped and named in did; the reply handler takes the composer's pick; the composer's HTMX pieces. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28);
$t = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE canned target', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
$cid = mkcanned($lena, ['title' => 'SMOKE pending reply', 'body' => 'Hi {{requester.first_name}}, we ordered the part.', 'scope' => 'queue', 'queue' => $W['it'], 'side_effects' => ['status' => 'pending', 'add_tags' => 'hardware']]);
echo "1. send=no\n";
$n = count(messages_of($t));
[$c, $b] = act($marco, '/canned/apply.php', ['ticket' => $t, 'canned' => $cid, 'send' => 'no']);
ok($c === 200 && ($b['text'] ?? '') === 'Hi SMOKE, we ordered the part.' && ($b['side_effects'] ?? []) === ['→ Pending', '+hardware'] && count(messages_of($t)) === $n, 'the text and the chips; no message written');
echo "2. send=yes\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/canned/apply.php', ['ticket' => $t, 'canned' => $cid, 'send' => 'yes']);
$msgs = messages_of($t);
$last = end($msgs);
ok($c === 200 && count($msgs) === $n + 1 && $last['kind'] === 'public_reply' && $last['channel'] === 'web' && (int) $last['author_member_id'] === 27 && $last['body_text'] === 'Hi SMOKE, we ordered the part.', 'one public reply by Marco on the web channel with the rendered text');
ok(ticket_status($t) === 'pending' && in_array('hardware', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :t', ['t' => $t])), true), '→ Pending and +hardware applied');
ok((int) canned_row($cid)['usage_count'] === 1, 'usage_count bumped');
$ca = array_values(array_filter(activity('canned.apply', $since), fn ($r) => (int) $r['ticket_id'] === $t));
$a = json_decode((string) ($ca[0]['after'] ?? '{}'), true);
ok(count($ca) === 1 && $a['canned_id'] === $cid && $a['sent'] === true && $a['side_effects']['applied'] === ['+hardware', '→ Pending'] && $a['side_effects']['skipped'] === [], 'canned.apply logged with the canned id, sent, the side-effects applied');
ok(count(array_filter(activity('ticket.reply', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1 && count(array_filter(activity('ticket.transition', $since), fn ($r) => (int) $r['ticket_id'] === $t && json_decode($r['after'], true)['via'] === 'canned')) === 1 && count(array_filter(activity('ticket.tag', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1, 'beside it: ticket.reply, ticket.transition (via canned), ticket.tag');
ok(($b['location'] ?? '') === '/tickets/' . $t . '?notice=sent#message-' . $last['id'] && str_contains((string) $b['did'], '→ Pending'), 'lands on the message; did names the side-effects');
$ob = outbox($t, 'replied'); $lastOb = end($ob);
ok(count($ob) >= 1 && str_contains($lastOb['body'], 'we ordered the part'), 'Jo is told by email with the text');
echo "3. A side-effect the table forbids\n";
$t2 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE canned close', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
$closer = mkcanned($lena, ['title' => 'SMOKE closer', 'body' => 'Closing this.', 'scope' => 'global', 'side_effects' => ['status' => 'closed', 'priority' => 'low']]);
$since = last_activity_id();
[$c, $b] = act($marco, '/canned/apply.php', ['ticket' => $t2, 'canned' => $closer, 'send' => 'yes']);
ok($c === 200 && ticket_status($t2) === 'new' && ticket_row($t2)['priority'] === 'low' && str_contains((string) $b['did'], 'skipped status:') && str_contains((string) $b['did'], 'cannot move from New to Closed'), '→ Closed from New is skipped and named in did; ↓ Low applied; the reply sent (' . $b['did'] . ')');
$a = json_decode((string) array_values(array_filter(activity('canned.apply', $since), fn ($r) => (int) $r['ticket_id'] === $t2))[0]['after'], true);
ok(count($a['side_effects']['skipped']) === 1 && $a['side_effects']['skipped'][0]['effect'] === 'status', 'the log names the skipped effect');
[$c, $b] = act($marco, '/canned/apply.php', ['ticket' => $t2, 'canned' => $closer, 'send' => 'yes', 'apply_side_effects' => 'no']);
ok($c === 200 && ($b['side_effects']['applied'] ?? null) === [] && (int) canned_row($closer)['usage_count'] === 2, 'apply_side_effects=no: the reply only; usage still bumped');
echo "4. The reply handler takes the composer's pick\n";
$t3 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE canned via reply', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
$since = last_activity_id();
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t3, 'body' => 'Hi SMOKE, we ordered the part. (edited)', 'canned_id' => $cid, 'apply_side_effects' => 'yes']);
ok($c === 200 && ticket_status($t3) === 'pending' && (int) canned_row($cid)['usage_count'] === 2 && count(array_filter(activity('canned.apply', $since), fn ($r) => (int) $r['ticket_id'] === $t3)) === 1 && str_contains((string) $b['did'], '→ Pending'), 'ticket_reply with canned_id + apply_side_effects: the effects applied, usage bumped, canned.apply logged');
$t4 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE canned via reply, no effects', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t4, 'body' => 'plain', 'canned_id' => $cid, 'apply_side_effects' => 'no']);
ok($c === 200 && ticket_status($t4) === 'new', 'with apply_side_effects=no the status stays');
echo "5. The composer's HTMX pieces\n";
$body = page($marco, '/tickets/' . $t4)['body'];
ok(str_contains($body, 'id="ticket-reply-canned-btn"') && str_contains($body, 'hx-get="/canned/?picker=1&amp;ticket=' . $t4 . '"') && str_contains($body, 'id="canned-picker"') && str_contains($body, 'id="ticket-reply-canned-effects"'), 'the composer has the Canned button, the picker region and the effects region');
$r = req('GET', '/canned/?picker=1&ticket=' . $t4 . '&q=pending', ['jar' => $marco, 'headers' => ['HX-Request: true']]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="canned-pick-' . $cid . '"') && !str_contains($r['body'], 'id="canned-pick-' . $closer . '"') && str_contains($r['body'], 'id="canned-picker-q"'), 'the picker partial filters by the words');
[$c, $html, $h] = hx($marco, '/canned/apply.php', ['ticket' => $t4, 'canned' => $cid, 'send' => 'no', 'body' => "Dear Jo,\nMORE", 'caret' => '8'], '#ticket-reply-form-field-body');
ok($c === 200 && preg_match('#<textarea name="body" id="ticket-reply-form-field-body"[^>]*>Dear Jo,\nHi SMOKE, we ordered the part\.\nMORE</textarea>#', $html) === 1, 'the HTMX answer is the textarea with the text inserted at the caret');
ok(str_contains($html, 'id="ticket-reply-canned-effects" hx-swap-oob="true"') && str_contains($html, 'name="canned_id" value="' . $cid . '"') && str_contains($html, 'name="apply_side_effects" value="yes"') && str_contains($html, '→ Pending'), 'with the side-effect chips and the checkbox out-of-band');
ok(count(messages_of($t4)) === 2, 'and no message written');
$body = page($marco, '/tickets/' . $t4)['body'];
// The shell's ONE modal is the record picker's (#record-picker, docs/record-picker.md) — the second exemption to "no modals" beside hx-confirm; it is taken out first.
$bodyNoPicker = preg_replace('#<div class="modal fade" id="record-picker".*?id="record-picker-create-btn">.*?</button>\s*</div>\s*</div>\s*</div>\s*</div>#s', '', $body);
ok(!str_contains($bodyNoPicker, 'modal') && $bodyNoPicker !== $body, 'no modal anywhere on the ticket page (the record picker\'s is the one exception)');
finish();
